import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-DrdKnICy.js";var i=JSON.parse(`{"path":"/software-exam/integrated/project-quality-management/comprehensive-exercises/","title":"1 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"1 综合练习","createTime":"2026-11-21T20:10:00.000Z","permalink":"/software-exam/integrated/project-quality-management/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":63.17,"words":18951},"git":{"createdTime":1795264775000},"filePathRelative":"software-exam/integrated/project-quality-management/1.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`1.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> （ ）是识别项目及其可交付成果的质量要求、标准，并书面描述项目将如何证明符合质量要求、标准的过程。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．检查质量</li></ul><details class="quiz" data-q="1" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：规划质量管理就是识别项目及其可交付成果的质量要求、标准，并书面描述项目如何证明符合质量要求与标准的过程（P410）　<span class="quiz-src">自编</span></p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> 在规划质量管理时，（ ）提供了记录干系人需求和期望的方法。</p><ul><li>A．需求管理计划</li><li>B．风险管理计划</li><li>C．干系人参与计划</li><li>D．范围基准</li></ul><details class="quiz" data-q="2" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：需求管理计划提供识别、分析和管理需求的方法，风险管理计划提供识别、分析和监督风险的方法，只有干系人参与计划提供记录干系人需求和期望的方法；范围基准用于考虑范围说明书中可交付成果的验收标准（P411）　<span class="quiz-src">自编</span></p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 某公司在教育服务领域持续发展，已有丰富的项目经验。近日新立项的教育服务项目 A 需要规划质量管理，则应采用（ ）的方法。</p><ul><li>A．成本收益分析法</li><li>B．质量成本法</li><li>C．标杆对照法</li><li>D．实验设计</li></ul><details class="quiz" data-q="3" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：本项目属公司熟悉的领域且已有丰富经验，宜用标杆对照法，将实际或计划的实践与可比项目比较以识别最佳实践、形成改进意见（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> （ ）有助于了解项目和产品质量的隐性和显性、正式和非正式的需求和期望。</p><ul><li>A．标杆对照</li><li>B．头脑风暴</li><li>C．访谈</li><li>D．成本效益分析</li></ul><details class="quiz" data-q="4" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：访谈有助于了解项目和产品质量的隐性与显性、正式与非正式的需求和期望；标杆对照用于与可比实践比较找最佳实践，头脑风暴用于向团队成员或专家收集数据，成本效益分析用于估算备选方案优势劣势（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 为保证项目实施质量，公司组织项目成员进行了三天专业知识培训，该培训成本属于（ ）。</p><ul><li>A．内部失败成本</li><li>B．外部失败成本</li><li>C．评估成本</li><li>D．预防成本</li></ul><details class="quiz" data-q="5" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：质量成本分一致性成本与不一致成本，培训、文件过程、设备、完成时间属一致性成本中的预防成本，用于打造高质量产品（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 管理质量成本属于质量成本中的（ ）成本。</p><ul><li>A．一致性</li><li>B．内部失败</li><li>C．非一致性</li><li>D．外部失败</li></ul><details class="quiz" data-q="6" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理质量成本属于质量成本框架中的一致性成本（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 与项目有关的质量成本（COQ）包含以下一种或多种成本：（ ）、评估成本、失败成本（内部/外部）。</p><ul><li>A．纠错成本</li><li>B．开发成本</li><li>C．测试成本</li><li>D．预防成本</li></ul><details class="quiz" data-q="7" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：COQ 由预防成本、评估成本和失败成本（内部/外部）构成，最优 COQ 是在预防成本与评估成本之间找到恰当投资平衡点以规避失败成本（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> 在收集需求时，使用问卷调查收集关于客户期望的数据属于（ ）</p><ul><li>A．预防成本</li><li>B．评估成本</li><li>C．内部失败成本</li><li>D．外部失败成本</li></ul><details class="quiz" data-q="8" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：收集需求时质量尚未发生问题，故属一致性成本中的预防成本，用于收集客户期望（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 下面属于不一致性成本的是（ ）。</p><ul><li>A．测试</li><li>B．破坏性试验损失</li><li>C．检查</li><li>D．返工</li></ul><details class="quiz" data-q="9" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：测试、破坏性试验损失、检查均属一致性成本中的评估成本，只有返工属不一致成本（内部失败成本）（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> 项目有关的质量成本中，属于不一致成本的是（ ）。</p><ul><li>A．预防成本</li><li>B．评估成本</li><li>C．破坏性试验损失成本</li><li>D．外部失败成本</li></ul><details class="quiz" data-q="10" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：预防成本、评估成本（含破坏性试验损失）属一致性成本，外部失败成本（债务、保修工作、失去业务）属不一致成本（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> 质量成本中（ ）属于非一致性成本。</p><ul><li>A．返工</li><li>B．培训</li><li>C．测试</li><li>D．检查</li></ul><details class="quiz" data-q="11" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：返工属不一致成本中的内部失败成本，培训属预防成本、测试与检查属评估成本，均为一致性成本（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 某电池生产厂商为了保证产品的质量，在每一块电池出厂前做破坏性测试所产生的成本属于（ ）。</p><ul><li>A．项目开发成本，不属于质量成本</li><li>B．质量成本中的非一致性成本</li><li>C．质量成本中的评价成本</li><li>D．质量生产中的内部失败成本</li></ul><details class="quiz" data-q="12" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：出厂前破坏性测试属于评估（评价）质量所花的费用，归入一致性成本中的评估成本（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> （ ）用来显示将一个或多个输入转化成一个或多个输出的过程中，有助于了解和估算一个过程的质量成本。</p><ul><li>A．流程图</li><li>B．矩阵图</li><li>C．思维导图</li><li>D．逻辑数据模型</li></ul><details class="quiz" data-q="13" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：流程图（也称过程图、过程流向图）显示一个或多个输入转化为一个或多个输出的过程，有助于了解和估算过程的质量成本，并可识别可能出现质量缺陷或需纳入质量检查的地方（P413）　<span class="quiz-src">自编</span></p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> （ ）把组织数据可视化，用业务语言加以描述，不依赖任何特定技术，可用于识别会出现数据完整性或其他问题的地方。</p><ul><li>A．流程图</li><li>B．矩阵图</li><li>C．思维导图</li><li>D．逻辑数据模型</li></ul><details class="quiz" data-q="14" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：逻辑数据模型把组织数据可视化、用业务语言描述且不依赖特定技术，可用于识别数据完整性或其他问题出现的地方（P413）　<span class="quiz-src">自编</span></p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> （ ）展示因素、原因和目标之间的强弱关系，有助于识别对项目成功至关重要的质量测量指标。</p><ul><li>A．流程图</li><li>B．矩阵图</li><li>C．思维导图</li><li>D．逻辑数据模型</li></ul><details class="quiz" data-q="15" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：矩阵图在行列交叉位置展示因素、原因和目标之间的强弱关系，规划质量管理时有助于识别对项目成功至关重要的质量测量指标（P413）　<span class="quiz-src">自编</span></p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 质量成本包括预防不符合要求，为评价产品或服务是否符合要求，以及因未达到要求而发生的所有成本，对于质量保证人员而言，其职业生涯过程中往往处于因不产生效益而尴尬的境地，从质量成本角度来看，其原因是质量保证工作发生的成本属于（ ）。</p><ul><li>A．预防成本</li><li>B．外部失败成本</li><li>C．内部失败成本</li><li>D．评价成本</li></ul><details class="quiz" data-q="16" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：质量保证是为预防质量不符合标准而采取的一系列措施，故其成本属于预防成本（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 某软件系统经测试发现有错误并不能满足质量要求，为了纠正其错误投入了 10 人天的成本，该成本（ ）。</p><ul><li>A．是开发成本并不属于质量成本</li><li>B．是开发成本也属于质量成本的一致成本</li><li>C．属于质量成本中的故障成本</li><li>D．属于质量成本中的评估成本</li></ul><details class="quiz" data-q="17" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：为处理（纠正）已发生的错误所花的成本属于不一致成本中的故障（失败）成本（P412）　<span class="quiz-src">自编</span></p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> （ ）有助于识别对项目成功至关重要的质量测量指标。</p><ul><li>A．流程图</li><li>B．矩阵图</li><li>C．思维导图</li><li>D．亲和图</li></ul><details class="quiz" data-q="18" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：矩阵图在行列交叉位置展示因素、原因和目标之间的强弱关系，规划质量管理时有助于识别对项目成功至关重要的质量测量指标（P413）　<span class="quiz-src">自编</span></p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> （ ）不属于质量管理计划的内容。</p><ul><li>A．项目的质量目标</li><li>B．质量角色与职责</li><li>C．项目使用的质量工具</li><li>D．质量成本的分类</li></ul><details class="quiz" data-q="19" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：质量管理计划一般包括采用的质量标准、质量目标、质量角色与职责、需质量审查的可交付成果和过程、规划的质量控制和质量管理活动、使用的质量工具、与项目有关的主要程序，不含质量成本分类（P414）　<span class="quiz-src">自编</span></p></details><p><a id="q20" class="quiz-anchor"></a></p><p><strong>20.</strong> （ ）专用于描述项目或产品属性，以及控制质量过程将如何验证符合程度。</p><ul><li>A．质量测量指标</li><li>B．质量控制测量结果</li><li>C．质量管理计划</li><li>D．质量报告</li></ul><details class="quiz" data-q="20" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：质量测量指标专用于描述项目或产品属性，以及控制质量过程将如何验证符合程度（P417）　<span class="quiz-src">自编</span></p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 规划质量管理的输入不包括（ ）。</p><ul><li>A．干系人参与计划</li><li>B．需求文件</li><li>C．质量测量指标</li><li>D．范围基准</li></ul><details class="quiz" data-q="21" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：质量测量指标是规划质量管理的输出，而非输入；规划质量管理的输入为项目管理计划与项目文件（P417）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> 下列各项成本中，属于不一致成本的是（ ）。</p><p>①检查费；②培训费；③债务；④保修工作；⑤测试；⑥报废</p><ul><li>A．①②③</li><li>B．②③⑥</li><li>C．④⑤⑥</li><li>D．③④⑥</li></ul><details class="quiz" data-q="22" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：检查费、培训费、测试属一致性成本（预防成本与评估成本），债务、保修工作属外部失败成本、报废属内部失败成本，三者均为不一致成本（P412）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> 公司开发新设备前期培训属于（ ）成本。</p><ul><li>A．评估成本</li><li>B．预防成本</li><li>C．内部失败成本</li><li>D．外部失败成本</li></ul><details class="quiz" data-q="23" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：前期培训属一致性成本中的预防成本，用于打造高质量产品、规避失败（P412）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> （ ）是在行列交叉的位置展示因素、原因和目标之间的关系强弱。</p><ul><li>A．矩阵图</li><li>B．直方图</li><li>C．甘特图</li><li>D．亲和图</li></ul><details class="quiz" data-q="24" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：矩阵图在行列交叉位置展示因素、原因和目标之间的强弱关系，规划质量管理时有助于识别对项目成功至关重要的质量测量指标（P413）　<span class="quiz-src">2023 年下高项第 2 批</span></p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 与项目有关的质量成本（COQ）包含以下一种或多种成本：（ ）、评估成本、失败成本（内部/外部）。</p><ul><li>A．纠错成本</li><li>B．开发成本</li><li>C．测试成本</li><li>D．预防成本</li></ul><details class="quiz" data-q="25" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：COQ 由预防成本、评估成本（评估、测量、审计和测试）与失败成本（内部/外部，因产品或服务与干系人需求或期望不一致所致）构成，最优 COQ 是在预防与评估成本间找到恰当投资平衡点（P412）　<span class="quiz-src">2023 年下高项第 4 批</span></p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 在规划质量管理过程中，确定项目和产品质量标准时的正确做法是（ ）。</p><ul><li>A．使用决策分析识别达到项目目标所需的关键活动</li><li>B．使用回归分析展示项目团队成员技能分布</li><li>C．使用流程图分析评估项目成本与质量之间的关系</li><li>D．使用因果图监控项目过程中的质量和性能表现</li></ul><details class="quiz" data-q="26" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：流程图映射价值链条上的活动、决策点、分支循环与并行路径，有助于了解和估算过程的质量成本；决策分析、回归分析、因果图均非规划质量管理的工具技术（P413）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> 以下质量成本项中，属于预防成本的是（ ），属于内部失败成本的是（ ）。</p><ul><li>A．返工费用、债务成本</li><li>B．测试成本、保修工作</li><li>C．培训费用、报废成本</li><li>D．债务成本、返工费用</li></ul><details class="quiz" data-q="27" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：培训费用属预防成本，报废属内部失败成本；返工属内部失败，债务、保修工作属外部失败成本，测试属评估成本（P412）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> （ ）包含项目需要遵循的行业标准与准则。</p><ul><li>A．范围管理计划</li><li>B．资源管理计划</li><li>C．质量管理计划</li><li>D．范围基准</li></ul><details class="quiz" data-q="28" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：质量管理计划包含项目需遵循的行业标准与准则，这些标准与准则应写入招标文件（如建议邀请书）并在合同中引用，也可用于供应商资格预审或供应商甄选（P451）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> 质量成本分为预防成本、评估成本和失败成本。系统集成项目中，（ ）的费用应计入失败成本。</p><ul><li>A．聘请第三方实验室对节点进行压力测试</li><li>B．按照培训计划对运维人员进行培训</li><li>C．因设备异常导致业务中断赔偿用户</li><li>D．为避免掉线定期检查存储设备</li></ul><details class="quiz" data-q="29" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：产品已交付后因质量问题（设备异常）给客户造成损失而支付的赔偿属典型的外部失败成本；压力测试属评估成本，培训与定期检查防故障属预防成本　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> （ ）是外部失败成本。</p><ul><li>A．项目过程中发现问题需要返工</li><li>B．项目过程中发现问题无法修复</li><li>C．收到售后问题反馈后安排上门服务</li><li>D．花费资金进行破坏性检查</li></ul><details class="quiz" data-q="30" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：外部失败成本是客户发现的失败，包括债务、保修工作、失去业务；返工、报废属内部失败成本，破坏性检查属评估成本（P412）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> （ ）可用于识别关键事项和合适的备选方案，并通过一系列决策排列出备选方案的优先顺序。</p><ul><li>A．多标准决策分析</li><li>B．测试与检查的规划</li><li>C．逻辑数据模型</li><li>D．备选方案分析</li></ul><details class="quiz" data-q="31" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：多标准决策分析是规划质量管理中的决策技术，工具如优先矩阵，先对标准排序加权再应用于备选方案、按得分排序，从而排出质量测量指标等的优先顺序（P412-413）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> （ ）是把组织的质量政策用于项目，并将质量管理计划转化为可执行的质量活动的过程。</p><ul><li>A．管理质量</li><li>B．规划质量管理</li><li>C．控制质量</li><li>D．监督质量</li></ul><details class="quiz" data-q="32" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理质量是把组织的质量政策用于项目，并将质量管理计划转化为可执行的质量活动的过程（P472）　<span class="quiz-src">自编</span></p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> （ ）的作用是识别无效过程和导致质量低劣的原因。</p><ul><li>A．规划质量</li><li>B．控制质量</li><li>C．评估质量</li><li>D．管理质量</li></ul><details class="quiz" data-q="33" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理质量的作用是提高实现质量目标的可能性，以及识别无效过程和导致质量低劣的原因，促进过程改进（P472）　<span class="quiz-src">自编</span></p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> 下面那个选项不属于管理质量的作用（ ）。</p><ul><li>A．通过执行有关产品特定方面的设计准则，设计出最优的成熟产品</li><li>B．建立信心，可以使未来输出在完工时满足特定的需求和期望</li><li>C．确保使用质量过程并确保其使用能够满足项目的质量目标</li><li>D．核实项目可交付成果和工作已经达到主要干系人的质量要求，可供最终验收</li></ul><details class="quiz" data-q="34" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理质量有助于按设计准则设计最优成熟产品、建立信心、确保质量过程满足质量目标并提高过程效率与干系人满意度；核实可交付成果已达干系人质量要求可供最终验收属控制质量的作用（P473）　<span class="quiz-src">自编</span></p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> 以下不属于管理质量活动的是（ ）。</p><ul><li>A．故障分析</li><li>B．实验设计</li><li>C．质量改进</li><li>D．系统测试</li></ul><details class="quiz" data-q="35" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目经理和团队可通过组织的质量保证部门或其他组织职能执行故障分析、实验设计、质量改进等管理质量活动，系统测试属控制质量活动（P473）　<span class="quiz-src">自编</span></p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> 关于管理质量的说法中不正确的是（ ）。</p><ul><li>A．管理质量有时被称为&quot;质量保证&quot;，但&quot;管理质量&quot;的定义比&quot;质量保证&quot;更广，因其可用于非项目工作</li><li>B．质量保证着眼于项目使用的过程，旨在高效地执行项目过程</li><li>C．管理质量的工作属于质量成本框架中的一致性工作</li><li>D．在敏捷型项目中，质量管理通常是特定团队成员的职责</li></ul><details class="quiz" data-q="36" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：敏捷型项目中整个项目期间的质量管理由所有团队成员执行，传统项目中质量管理才通常是特定团队成员的职责（P473）　<span class="quiz-src">自编</span></p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 以下关于管理的叙述中，不正确的是（ ）。</p><ul><li>A．管理质量是把组织的质量政策用于项目，并将质量管理计划转化为可执行的质量活动的过程</li><li>B．管理质量是通过执行产品检查并发现缺陷来实现的</li><li>C．质量测量指标是管理质量的输入</li><li>D．管理质量活动可由第三方团队进行监督，适当时提供服务支持</li></ul><details class="quiz" data-q="37" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：执行产品检查并发现缺陷是控制质量的实现方式，管理质量靠质量保证与过程改进实现　<span class="quiz-src">自编</span></p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 以下不属于管理质量过程工作的是（ ）</p><ul><li>A．确保项目工作过程和工作成果达到质量测量指标及质量标准</li><li>B．根据风险评估报告识别与处置项目质量目标的机会和威胁，以便提出必要的变更请求</li><li>C．根据质量控制测量结果评价质量管理绩效及质量管理体系的合理性，以便提出必要的变更请求，实现过程改进</li><li>D．在用户验收和最终交付之前，测量产品或服务的完整性、合规性和适用性</li></ul><details class="quiz" data-q="38" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理质量过程包括执行质量管理计划中的活动、把标准与指标转化为测试与评估文件、据风险评估报告识别机会与威胁、据质量控制测量结果评价绩效与体系合理性、持续优化改进、编制质量报告等；验收前测量完整性合规性适用性属控制质量（P473-474）　<span class="quiz-src">自编</span></p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> 以下关于管理质量的叙述中，不正确的是（ ）。</p><ul><li>A．管理质量应该贯穿整个项目生命周期</li><li>B．管理质量活动属于监控过程组</li><li>C．管理质量的工作属于质量成本框架中的一致性工作</li><li>D．管理质量决定了项目质量控制的结果</li></ul><details class="quiz" data-q="39" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：管理质量活动属于执行过程组，而不是监控过程组　<span class="quiz-src">自编</span></p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> 质量控制测量结果是（ ）的过程输入。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．检查质量</li></ul><details class="quiz" data-q="40" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：可作为管理质量过程输入的项目文件包括经验教训登记册、质量控制测量结果、质量测量指标和风险报告等（P474）　<span class="quiz-src">自编</span></p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> （ ）用于分析和评估项目过程和可交付成果的质量是否符合执行组织的标准或特定要求。</p><ul><li>A．质量控制测量结果</li><li>B．核对单</li><li>C．控制质量</li><li>D．质量测量指标</li></ul><details class="quiz" data-q="41" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：质量控制测量结果用于分析和评估项目过程和可交付成果的质量是否符合执行组织的标准或特定要求（P474）　<span class="quiz-src">自编</span></p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> （ ）是一种结构化工具，通常列出特定组成部分，用来核实所要求的一系列步骤是否已得到执行或检查需求列表是否已得到满足。</p><ul><li>A．核对单</li><li>B．核查表</li><li>C．文件分析</li><li>D．矩阵图</li></ul><details class="quiz" data-q="42" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：核对单是一种结构化工具，通常列出特定组成部分，用来核实所要求的一系列步骤是否已得到执行或检查需求列表是否已得到满足（P474）　<span class="quiz-src">自编</span></p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> （ ）用于分析质量控制测量结果、质量测试与评估结果、质量报告等，以便判断质量过程的实施情况好坏。</p><ul><li>A．备选方案分析</li><li>B．文件分析</li><li>C．过程分析</li><li>D．根本原因分析</li></ul><details class="quiz" data-q="43" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：文件分析用于分析质量控制测量结果、质量测试与评估结果、质量报告等，以便判断质量过程的实施情况好坏（P474）　<span class="quiz-src">自编</span></p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> （ ）用于把一个生产过程分解成若干环节，逐一加以分析，发现最值得改进的环节。</p><ul><li>A．备选方案分析</li><li>B．文件分析</li><li>C．过程分析</li><li>D．根本原因分析</li></ul><details class="quiz" data-q="44" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：过程分析用于把一个生产过程分解成若干环节，逐一加以分析，发现最值得改进的环节（P474-475）　<span class="quiz-src">自编</span></p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 管理质量的数据表现技术中，&quot;对导致质量问题的各种原因进行归类，展示最应关注的领域&quot;的技术称为（ ）。</p><ul><li>A．因果图</li><li>B．亲和图</li><li>C．直方图</li><li>D．散点图</li></ul><details class="quiz" data-q="45" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：亲和图用于根据其亲近关系对导致质量问题的各种原因进行归类，展示最应关注的领域（P475）　<span class="quiz-src">自编</span></p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> （ ）用来分析导致某一结果的一系列原因，有助于人们进行创造性、系统性思维，找出问题的根源。</p><ul><li>A．因果图</li><li>B．亲和图</li><li>C．直方图</li><li>D．散点图</li></ul><details class="quiz" data-q="46" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：因果图也叫鱼刺图或石川图，用来分析导致某一结果的一系列原因，有助于人们进行创造性、系统性思维，找出问题的根源（P475）　<span class="quiz-src">自编</span></p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> （ ）展示了引发缺陷的一系列步骤，用于完整地分析某个或某类质量问题产生的全过程。</p><ul><li>A．因果图</li><li>B．亲和图</li><li>C．直方图</li><li>D．流程图</li></ul><details class="quiz" data-q="47" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：流程图展示了引发缺陷的一系列步骤，用于完整地分析某个或某类质量问题产生的全过程（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> （ ）是一种展示数字数据的条形图，可展示每个可交付成果的缺陷数量、缺陷成因排列、各个过程的不合规次数，或项目或产品缺陷的其他表现形式。</p><ul><li>A．因果图</li><li>B．亲和图</li><li>C．直方图</li><li>D．散点图</li></ul><details class="quiz" data-q="48" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：直方图是显示各种问题分布情况的柱状图，每个柱子代表一个问题、柱高代表出现次数，可展示缺陷数量、缺陷成因排列、过程不合规次数等（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> （ ）在行列交叉的位置展示因素、原因和目标之间的关系强弱。</p><ul><li>A．矩阵图</li><li>B．亲和图</li><li>C．直方图</li><li>D．散点图</li></ul><details class="quiz" data-q="49" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：矩阵图在行列交叉的位置展示因素、原因和目标之间的关系强弱（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> （ ）用于表示同属一组变量的各个变量之间的关系。</p><ul><li>A．屋顶形</li><li>B．L 形</li><li>C．T 形</li><li>D．Y 形</li></ul><details class="quiz" data-q="50" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：屋顶形矩阵图用于表示同属一组变量的各个变量之间的关系（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> （ ）用于表示一组变量分别与另两组变量的关系，后两组变量之间没有关系。</p><ul><li>A．屋顶形</li><li>B．L 形</li><li>C．T 形</li><li>D．Y 形</li></ul><details class="quiz" data-q="51" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：T 形矩阵图用于表示一组变量分别与另两组变量的关系，后两组变量之间没有关系（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> （ ）是一种展示两个变量之间的关系的图形，它能够展示两支轴的关系，一般一支轴表示过程、环境或活动的任何要素，另一支轴表示质量缺陷。</p><ul><li>A．因果图</li><li>B．亲和图</li><li>C．直方图</li><li>D．散点图</li></ul><details class="quiz" data-q="52" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：散点图展示两个变量之间的关系，一支轴表示过程、环境或活动的任何要素，另一支轴表示质量缺陷（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> 对质量管理活动进行结构性审查，决定一个项目质量活动是否符合组织政策、过程和程序的独立的评估活动称为（ ）。</p><ul><li>A．过程分析</li><li>B．基准分析</li><li>C．整体审计</li><li>D．质量审计</li></ul><details class="quiz" data-q="53" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：审计是用于确定项目活动是否遵循了组织和项目的政策、过程与程序的一种结构化且独立的过程（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 关于质量审计的说法中不正确的是（ ）。</p><ul><li>A．审计是用于确定项目活动是否遵循了组织和项目的政策、过程与程序的一种结构化且独立的过程</li><li>B．为了保证审计的真实性，质量审计只能由组织外部的团队开展</li><li>C．质量审计可事先安排，也可随机进行</li><li>D．质量审计还可确认已批准的变更请求（包括更新、纠正措施、缺陷补救和预防措施）的实施情况</li></ul><details class="quiz" data-q="54" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：质量审计通常由项目外部的团队开展，如组织内部审计部门、项目管理办公室（PMO）或组织外部的审计师，并非只能由外部团队开展（P476）　<span class="quiz-src">自编</span></p></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> 质量审计目标不包括（ ）。</p><ul><li>A．识别全部正在实施的良好及最佳实践</li><li>B．识别所有违规做法、差距及不足</li><li>C．分享所在组织和/或行业中类似项目的良好实践</li><li>D．保证软件系统或软件产品充分满足用户要求的质量而进行的有计划、有组织的活动</li></ul><details class="quiz" data-q="55" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：质量审计目标包括识别正在实施的良好及最佳实践、识别违规做法与差距不足、分享类似项目的良好实践、主动提供协助改进过程、积累经验教训知识库；D 项是质量保证的定义而非审计目标（P477）　<span class="quiz-src">自编</span></p></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> （ ）旨在使生产过程更加顺畅、稳定，减少生产过程中的浪费及降低产品缺陷率。</p><ul><li>A．过程改进</li><li>B．质量保证</li><li>C．控制质量</li><li>D．面向 X 的设计</li></ul><details class="quiz" data-q="56" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：过程改进旨在使生产过程更加顺畅、稳定，减少生产过程中的浪费及降低产品缺陷率（P477）　<span class="quiz-src">自编</span></p></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 质量报告是那个过程的输出（ ）。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．检查质量</li></ul><details class="quiz" data-q="57" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：管理质量的输出为质量报告和测试与评估文件（P477-478）　<span class="quiz-src">自编</span></p></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> （ ）可能是图形、数据或定性文件，其中包含的信息可帮助其他过程和部门采取纠正措施，以实现项目质量期望。</p><ul><li>A．质量控制测量结果</li><li>B．质量测量指标</li><li>C．测试与评估文件</li><li>D．质量报告</li></ul><details class="quiz" data-q="58" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：质量报告可能是图形、数据或定性文件，其中包含的信息可帮助其他过程和部门采取纠正措施，以实现项目质量期望（P477）　<span class="quiz-src">自编</span></p></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> 过程改进通常是在（ ）过程中。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．检查质量</li></ul><details class="quiz" data-q="59" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：过程改进通常发生在管理质量过程中，要基于过程分析的结果，用质量改进方法去做过程改进（P477）　<span class="quiz-src">自编</span></p></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> （ ）表示三组变量之间的关系，三组变量都有关系。</p><ul><li>A．T 型</li><li>B．C 型</li><li>C．屋顶型</li><li>D．X 型</li></ul><details class="quiz" data-q="60" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：C 形矩阵图表示三组变量之间的关系，三组变量之间都有关系；T 型是一组对另两组、X 型是四组两两相关、屋顶型是同组各变量相关（P476）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> 某产品由于种种原因导致逾期交付，项目团队需要依据并联关系对导致质量问题的各种原因进行归类，找到导致预期的最应关注的领域，项目团队应使用（ ）。</p><ul><li>A．矩阵图</li><li>B．鱼骨图</li><li>C．流程图</li><li>D．亲和图</li></ul><details class="quiz" data-q="61" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：亲和图用于根据其亲近关系对导致质量问题的各种原因进行归类，展示最应关注的领域（P475）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> （ ）过程的作用之一是识别无效过程和导致质量低劣的原因。</p><ul><li>A．规划质量</li><li>B．管理质量</li><li>C．检查质量</li><li>D．控制质量</li></ul><details class="quiz" data-q="62" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：管理质量是把组织质量政策用于项目、把质量管理计划转化为可执行质量活动的过程，其主要作用是提高实现质量目标的可能性并识别无效过程和导致质量低劣的原因（P472）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> 在敏捷型项目中，整个项目期间的质量管理由（ ）执行，但在传统项目中，质量管理通常是（ ）的职责。</p><ul><li>A．所有团队成员、特定团队成员</li><li>B．特定团队成员、所有团队成员</li><li>C．所有团队成员、所有团队成员</li><li>D．特定团队成员、特定团队成员</li></ul><details class="quiz" data-q="63" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：敏捷型项目中整个项目期间的质量管理由所有团队成员执行，传统项目中质量管理通常是特定团队成员的职责（P473）　<span class="quiz-src">2023 年下高项第 1 批</span></p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> 以下关于问题解决，说法错误的是（ ）。</p><ul><li>A．问题解决发现解决问题或应对挑战的解决方案。它包括收集其他信息、具有批判性思维的、创造性的、量化的和或逻辑性的解决方法</li><li>B．问题可能在控制质量过程或质量审计中发现，也可能与过程或可交付成果有关</li><li>C．问题解决方法通常包括以下要素：定义问题，识别根本原因，生成可能的解决方案，选择最佳解决方案，执行解决方案，验证解决方案的有效性等</li><li>D．使用非结构化的方法解决问题有助于消除问题和制定长久有效的解决方案</li></ul><details class="quiz" data-q="64" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：问题解决是指用结构化的方法从根本上解决控制质量过程或质量审计中发现的质量管理问题，从定义问题、识别根本原因到形成备选方案、选择并实施既定方案、核实解决效果，非结构化方法无法保证长久有效（P372）　<span class="quiz-src">2023 年下高项第 4 批</span></p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> （ ）的作用是识别无效过程和导致质量低劣的原因。</p><ul><li>A．规划质量</li><li>B．控制质量</li><li>C．评估质量</li><li>D．管理质量</li></ul><details class="quiz" data-q="65" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理质量的作用是提高实现质量目标的可能性、识别无效过程和导致质量低劣的原因、使用控制质量过程的数据和结果向干系人展示项目总体质量状态（P472）　<span class="quiz-src">2023 年下高项第 4 批</span></p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 关于项目质量管理的描述，不正确的是：（ ）。</p><ul><li>A．质量管理由独立的质量保证团队在项目生命周期的特定阶段执行</li><li>B．质量目标是落实质量方针的具体要求，从属于质量方针</li><li>C．质量管理是为了实现质量目标而进行的所有质量性质的活动</li><li>D．质量方针是由组织最高管理者正式发布的该组织总的质量宗旨和方向</li></ul><details class="quiz" data-q="66" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理质量是所有人的共同职责，敏捷项目中整个项目期间由所有团队成员执行，传统项目中通常由特定团队成员承担，并非由独立质量保证团队在特定阶段执行（P473）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> 在执行质量管理相关过程时，质量经理对提交的成果进行了审查，将发现的问题记录并给出了纠正措施建议，该质量经理正在执行（ ）过程。</p><ul><li>A．控制质量</li><li>B．管理质量</li><li>C．规划质量管理</li><li>D．持续改进</li></ul><details class="quiz" data-q="67" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：对成果进行审查、记录问题并给出纠正措施建议属于管理质量中的质量审计活动；QA 做质量保证、QC 做控制质量，此题是质量经理在做事，故为管理质量（P473）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> 关于管理质量相关的描述，正确的是：（ ）。</p><ul><li>A．管理质量就是质量保证</li><li>B．管理质量的工作属于非一致性成本</li><li>C．管理质量与产品设计和过程改进无关</li><li>D．识别无效过程是管理质量的作用之一</li></ul><details class="quiz" data-q="68" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理质量的作用包括提高实现质量目标的可能性、识别无效过程和导致质量低劣的原因、使用控制质量数据向干系人展示总体质量状态（P472）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> （ ）用于根据其亲近关系对导致质量问题的各种原因进行归类，展示最应关注的领域；（ ）用来分析导致某一结果的一系列原因。</p><ul><li>A．因果图、亲和图</li><li>B．亲和图、流程图</li><li>C．因果图、流程图</li><li>D．亲和图、因果图</li></ul><details class="quiz" data-q="69" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：亲和图根据亲近关系对导致质量问题的各种原因归类、展示最应关注的领域；因果图也叫鱼刺图或石川图，用来分析导致某一结果的一系列原因，是根本原因分析的常用方法（P475）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> 在某电子产品制造项目中，质量团队采用因果图分析一批产品尺寸波动的根本原因，并据此生成了一份包含改进建议的质量报告，该活动属于（ ）过程的工作。</p><ul><li>A．控制质量</li><li>B．管理项目知识</li><li>C．规划质量管理</li><li>D．管理质量</li></ul><details class="quiz" data-q="70" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理质量的核心是把质量计划转化为执行活动，进行过程分析、改进并确保体系有效；用因果图做根本原因分析并输出含改进建议的质量报告正是该过程的典型活动与输出，控制质量的输出是核实的可交付成果与质量控制测量结果　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> （ ）不属于&quot;管理质量&quot;过程的主要工作。</p><ul><li>A．执行质量管理计划中规划的质量管理活动</li><li>B．编制质量报告</li><li>C．评价质量管理绩效并持续优化改进</li><li>D．确定质量标准和质量测量指标</li></ul><details class="quiz" data-q="71" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理质量的主要工作包括执行规划的质量管理活动、把质量标准与测量指标转化为测试与评估文件、据风险评估报告识别机会与威胁、据质量控制测量结果评价绩效与体系合理性并持续优化、编制质量报告等；确定质量标准和质量测量指标属规划质量管理（P473-474）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> （ ）是为了评估绩效，确保项目输出完整、正确且满足客户期望，而监督和记录质量管理活动执行结果的过程。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．确认质量</li></ul><details class="quiz" data-q="72" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：控制质量是为了评估绩效，确保项目输出完整、正确且满足客户期望，而监督和记录质量管理活动执行结果的过程（P498）　<span class="quiz-src">自编</span></p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> （ ）的主要作用是，核实项目可交付成果和工作已经达到主要干系人的质量要求，可供最终验收。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．确认质量</li></ul><details class="quiz" data-q="73" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：控制质量的主要作用是核实项目可交付成果和工作已经达到主要干系人的质量要求，可供最终验收（P498）　<span class="quiz-src">自编</span></p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> 抽样的频率和规模应在（ ）过程中确定。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．检查质量</li></ul><details class="quiz" data-q="74" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：抽样的频率和规模应在规划质量管理过程中确定（P500）　<span class="quiz-src">自编</span></p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> 质量控制的输入，不包括（ ）。</p><ul><li>A．项目管理计划</li><li>B．确认的变更</li><li>C．质量测量指标</li><li>D．工作绩效数据</li></ul><details class="quiz" data-q="75" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：控制质量输入为项目管理计划（质量管理计划）、项目文件（测试与评估文件、质量测量指标、经验教训登记册）、可交付成果、工作绩效数据、批准的变更请求；确认的变更不是输入（P499-500）　<span class="quiz-src">自编</span></p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> （ ）是控制质量过程的输入，用于评估质量目标的实现情况。</p><ul><li>A．质量测量指标</li><li>B．经验教训登记册</li><li>C．可交付成果</li><li>D．测试与评估文件</li></ul><details class="quiz" data-q="76" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：测试与评估文件是控制质量过程的输入，用于评估质量目标的实现情况（P499）　<span class="quiz-src">自编</span></p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> 下图属于质量管理中的（ ）工具。</p><table><thead><tr><th>缺陷/日期</th><th>日期1</th><th>日期2</th><th>日期3</th><th>日期4</th><th>合计</th></tr></thead><tbody><tr><td>小划痕</td><td>1</td><td>2</td><td>2</td><td>2</td><td>7</td></tr><tr><td>大划痕</td><td>0</td><td>1</td><td>0</td><td>0</td><td>1</td></tr><tr><td>弯曲</td><td>3</td><td>3</td><td>1</td><td>2</td><td>9</td></tr><tr><td>缺少组件</td><td>5</td><td>0</td><td>2</td><td>1</td><td>8</td></tr><tr><td>颜色配错</td><td>2</td><td>0</td><td>1</td><td>3</td><td>6</td></tr><tr><td>标签错误</td><td>1</td><td>2</td><td>1</td><td>2</td><td>6</td></tr></tbody></table><ul><li>A．核对单</li><li>B．核查表</li><li>C．统计抽样</li><li>D．矩阵图</li></ul><details class="quiz" data-q="77" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：核查表又称计数表，用于合理排列各种事项，以便有效地收集关于潜在质量问题的有用数据（P500）　<span class="quiz-src">自编</span></p></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 从 75 张工程图纸中随机抽取 10 张属于（ ）</p><ul><li>A．核对单</li><li>B．核查表</li><li>C．统计抽样</li><li>D．矩阵图</li></ul><details class="quiz" data-q="78" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：统计抽样是指从目标总体中选取部分样本用于检查，如从 75 张工程图纸中随机抽取 10 张（P500）　<span class="quiz-src">自编</span></p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> 在部署产品或服务之后，使用问卷调查收集识别的缺陷相关成本属于（ ）</p><ul><li>A．预防成本</li><li>B．评估成本</li><li>C．内部失败成本</li><li>D．外部失败成本</li></ul><details class="quiz" data-q="79" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：问卷调查可用于部署产品或服务之后收集客户满意度数据，其中识别出的缺陷相关成本可视为 COQ 模型中的外部失败成本（P500）　<span class="quiz-src">自编</span></p></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> （ ）用于比较和分析质量测量指标和实际结果测量。</p><ul><li>A．统计抽样</li><li>B．绩效审查</li><li>C．根本原因分析（RAC）</li><li>D．审计</li></ul><details class="quiz" data-q="80" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：绩效审查用于比较和分析质量测量指标和实际结果测量；统计抽样从目标总体中选取部分样本检查，根本原因分析用于识别缺陷成因（P500-501）　<span class="quiz-src">自编</span></p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> （ ）不属于控制质量过程的数据收集技术。</p><ul><li>A．核对单</li><li>B．核查表</li><li>C．统计抽样</li><li>D．绩效审查</li></ul><details class="quiz" data-q="81" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：核对单、核查表、统计抽样属于控制质量的数据收集技术，绩效审查属于控制质量的数据分析技术（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．测试的目的是找出产品或服务中存在的错误、缺陷、漏洞或其他不合规问题</li><li>B．测试只在项目结束时进行，目的是为了检测产品缺陷</li><li>C．软件测试可能包括单元测试、集成测试、接口测试等</li><li>D．硬件开发中，测试可能包括环境应力筛选、老化测试、系统测试</li></ul><details class="quiz" data-q="82" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：测试可以贯穿于整个项目，也可以在项目结束时进行，并非只在项目结束时进行（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> 下面那种测试一般由开发人员进行（ ）。</p><ul><li>A．单元测试</li><li>B．集成测试</li><li>C．回归测试</li><li>D．验收测试</li></ul><details class="quiz" data-q="83" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：一般单元测试由开发人员自行进行，主要是对模块或代码段进行测试（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> （ ）不属于控制质量过程的数据表现技术。</p><ul><li>A．思维导图</li><li>B．控制图</li><li>C．直方图</li><li>D．散点图</li></ul><details class="quiz" data-q="84" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：适用于控制质量过程的数据表现技术包括因果图、控制图、直方图和散点图等，不含思维导图（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> 在质量控制中，根据控制图七点运行定律，（ ）需要接受检查。</p><p>原题附图（略）：两幅质量控制图，横轴为 1～12 号数据点、均标有均线，图①的折线整体呈持续上升趋势，图②的折线整体呈持续下降趋势。</p><ul><li>A．只有①</li><li>B．只有②</li><li>C．①和②</li><li>D．①和②都没有</li></ul><details class="quiz" data-q="85" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：七点运行定律指质量控制图中一行上的 7 个数据点都低于平均值或高于平均值，或都是上升的、都是下降的，则该过程因非随机问题需要接受检查；图中连续 7 点呈持续下降的是②（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> 某系统上线后频繁收到发生闪退的用户投诉，项目经理安排工程师小王尽快找到故障原因，并推荐使用（ ）进行分析。</p><ul><li>A．鱼骨图</li><li>B．直方图</li><li>C．趋势图</li><li>D．散点图</li></ul><details class="quiz" data-q="86" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：因果图（鱼骨图）用于识别质量缺陷和错误可能造成的结果，可据此找故障原因（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> 质量管理工具（ ）常用于找出导致项目问题产生的潜在原因。</p><ul><li>A．控制图</li><li>B．鱼骨图</li><li>C．散点图</li><li>D．直方图</li></ul><details class="quiz" data-q="87" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：因果图（鱼骨图）用于识别质量缺陷和错误可能造成的结果，常用于找出导致项目问题产生的潜在原因（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> 质量控制的方法、技术和工具有很多，其中（ ）可以用来分析过程是否稳定，是否发生了异常情况。因果图直观地反映了项目中可能出现的问题与各种潜在原因之间的关系。</p><ul><li>A．因果图</li><li>B．控制图</li><li>C．散点图</li><li>D．帕累托图</li></ul><details class="quiz" data-q="88" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：控制图用于确定一个过程是否稳定、或是否具有可预测的绩效；因果图用于识别质量缺陷和错误可能造成的结果，散点图在一支轴上展示计划绩效、另一支轴展示实际绩效（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> （ ）可以作为项目质量控制中问题识别和问题分析的工具。</p><ul><li>A．帕累托分析</li><li>B．直方图</li><li>C．核对表</li><li>D．因果分析</li></ul><details class="quiz" data-q="89" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：因果图（因果分析）用于识别质量缺陷和错误可能造成的结果，可作为问题识别和问题分析的工具（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> （ ）是一种展示两个变量之间关系的图形，可在一支轴上展示计划的绩效，在另一支轴上展示实际绩效。</p><ul><li>A．流程图</li><li>B．直方图</li><li>C．矩阵图</li><li>D．散点图</li></ul><details class="quiz" data-q="90" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：散点图可在一支轴上展示计划的绩效，在另一支轴上展示实际绩效（P501）　<span class="quiz-src">自编</span></p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> （ ）不属于&quot;控制质量&quot;过程的输出。</p><ul><li>A．质量控制测量结果</li><li>B．质量报告</li><li>C．工作绩效信息</li><li>D．核实的可交付成果</li></ul><details class="quiz" data-q="91" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：控制质量的输出包括质量控制测量结果、核实的可交付成果、工作绩效信息、变更请求、项目管理计划更新和项目文件更新，质量报告是管理质量的输出（P502）　<span class="quiz-src">自编</span></p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> 在 A 项目的质量例会中，质量经理发现监控模块 BUG 修复时间较长，有测量指标超出临界线，质量经理决定在观察几天。本次质量控制的输出一定包括（ ）</p><p>①工作绩效信息；②变更请求；③经验教训文档；④质量控制测量结果；⑤更新的质量标准；⑥质量审计报告</p><ul><li>A．②③</li><li>B．①⑥</li><li>C．①④</li><li>D．②⑤</li></ul><details class="quiz" data-q="92" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：发现 BUG 修复时间较长即为测量结果，故有④质量控制测量结果；测量指标超出临界线是分析后的结果，故有①工作绩效信息；控制质量输出还包括核实的可交付成果、变更请求、计划与文件更新（P502）　<span class="quiz-src">自编</span></p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> 核实的可交付成果属于（ ）过程的输出。</p><ul><li>A．规划质量管理</li><li>B．管理质量</li><li>C．控制质量</li><li>D．检查质量</li></ul><details class="quiz" data-q="93" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：控制质量的输出有工作绩效信息、质量控制测量结果、核实的可交付成果、变更请求、项目管理计划更新、项目文件更新（P502）　<span class="quiz-src">自编</span></p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> （ ）是控制质量的输出，同时又是确认范围过程的输入。</p><ul><li>A．质量控制测量结果</li><li>B．变更请求</li><li>C．质量报告</li><li>D．核实的可交付成果</li></ul><details class="quiz" data-q="94" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：开展控制质量过程的结果是核实的可交付成果，它又是确认范围过程的一项输入，以便正式验收（P502）　<span class="quiz-src">自编</span></p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> （ ）是一种填满表格、合理排列各种事项，以便有效地收集关于潜在质量问题的工具。</p><ul><li>A．核查表</li><li>B．核对单</li><li>C．统计抽样</li><li>D．问卷调查</li></ul><details class="quiz" data-q="95" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：核查表又称计数表，用于合理排列各种事项，以便有效地收集关于潜在质量问题的有用数据（P500）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> 关于控制质量的描述，不正确的是（ ）。</p><ul><li>A．控制质量的目的是在用户验收和最终交付之前，测量产品或服务的完整性、合规性和适用性</li><li>B．控制质量时，控制图可用于确定一个过程是否稳定</li><li>C．在瀑布或预测型项目中，控制质量活动通常由特定团队成员在整个项目生命周期中持续执行</li><li>D．质量检查既可以针对单个活动的成果，也可以针对项目的最终产品</li></ul><details class="quiz" data-q="96" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：敏捷或适应型项目中控制质量活动可能由所有团队成员在整个项目生命周期中执行，瀑布或预测型项目中则由特定团队成员在特定时间点或项目/阶段快结束时执行（P499）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 以下（ ）属于控制质量的作用。</p><ul><li>A．识别无效过程</li><li>B．使用控制质量过程的数据和结果向干系人展示项目的总体质量状态</li><li>C．提高实现质量目标的可能性</li><li>D．确定项目输出是否达到预期目的，这些输出需要满足所有适用标准、要求、法规和规范。</li></ul><details class="quiz" data-q="97" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制质量是为了评估绩效、确保项目输出完整正确且满足客户期望，从而确定项目输出是否达到预期目的、是否满足所有适用标准要求法规和规范；识别无效过程、提高实现质量目标的可能性属管理质量的作用（P498）　<span class="quiz-src">2023 年下高项第 2 批</span></p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> 以下（ ）不属于质量控制的输入。</p><ul><li>A．可交付成果</li><li>B．工作绩效数据</li><li>C．测试与评估文件</li><li>D．质量控制测量结果</li></ul><details class="quiz" data-q="98" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：质量控制测量结果是控制质量的输出；其输入为项目管理计划、项目文件（经验教训登记册、质量测量指标、测试与评估文件）、批准的变更请求、可交付成果和工作绩效数据（P502）　<span class="quiz-src">2023 年下高项第 2 批</span></p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> 关于控制质量过程目的的描述，正确的是（ ）。</p><ul><li>A．在用户验收和最终交付之前测试产品或服务的完整性、合规性、适用性</li><li>B．识别项目及其可交付成果的质量要求、标准，并描述将如何证明符合质量要求</li><li>C．评估项目团队成员的绩效，确保项目输出敏捷、高效且满足管理层期望</li><li>D．着眼于项目后评估的过程，旨在高效地执行项目过程，包括遵守和满足标准</li></ul><details class="quiz" data-q="99" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制质量是为了评估绩效、确保项目输出完整正确且满足客户期望，主要作用是核实可交付成果和工作已达主要干系人质量要求可供最终验收，即在验收和最终交付前测试完整性、合规性与适用性（P498）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> 项目经理想要选取合适的数据表现技术控制质量，当他想要按照来源或组成部分展示缺陷数量时，应采用（ ），当他想同步展示计划绩效和实际绩效时应采用（ ）。</p><ul><li>A．直方图、散点图</li><li>B．散点图、控制图</li><li>C．直方图、控制图</li><li>D．控制图、直方图</li></ul><details class="quiz" data-q="100" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：直方图可按来源或组成部分展示缺陷数量，散点图可在一支轴上展示计划绩效、另一支轴展示实际绩效（P501）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> 控制质量输入中，（ ）用于评估质量目标的实现程度。</p><ul><li>A．测试与评估文件</li><li>B．经验教训登记册</li><li>C．项目管理计划</li><li>D．质量测量指标</li></ul><details class="quiz" data-q="101" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：测试与评估文件用于评估质量目标的实现程度（P499）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 某智能停车平台项目新增车牌识别项目，对 75 份接口规范文档质量的检查活动中，不正确的是（ ）。</p><ul><li>A．核查表统计缺陷数量</li><li>B．散点图展示缺陷数量</li><li>C．因果图追溯缺陷根源</li><li>D．控制图判断缺陷密度稳定</li></ul><details class="quiz" data-q="102" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：按来源或组成部分展示缺陷数量应用直方图，散点图用于在一支轴上展示计划绩效、另一支轴展示实际绩效（P501）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> 控制质量中，（ ）用于监控各项续航参数是否保持在预期界限内。</p><ul><li>A．控制图</li><li>B．因果图</li><li>C．直方图</li><li>D．散点图</li></ul><details class="quiz" data-q="103" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制图用于确定一个过程是否稳定或是否具有可预测的绩效，可监控各类输出变量是否保持在控制界限内（P501）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 关于控制质量过程中常用的数据表现技术，描述正确的是（ ）。</p><ul><li>A．控制图通过上下界限来监测各种输出变量是否稳定</li><li>B．因果图通过展示不同来源的缺陷数量来显示问题分布情况</li><li>C．亲和图用于识别质量缺陷和错误可能造成的结果</li><li>D．直方图用于回归分析两个变量之间的相关关系</li></ul><details class="quiz" data-q="104" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制图通过上下界限监测各种输出变量是否稳定；按来源或组成部分展示缺陷数量的是直方图，展示两个变量关系的是散点图，因果图才用于识别质量缺陷和错误可能造成的结果（P476）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> &quot;控制质量&quot;过程的主要输出不包括（ ）。</p><ul><li>A．质量控制测量结果</li><li>B．工作绩效信息</li><li>C．质量报告</li><li>D．核实的可交付成果</li></ul><details class="quiz" data-q="105" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：控制质量过程的输出为工作绩效信息、质量控制测量结果和核实的可交付成果，质量报告是管理质量过程的输出（P502）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q106" class="quiz-anchor"></a></p><p><strong>106.</strong> 关于控制图，以下情况需要检查的是（ ）。</p><p>①第 15 至 22 个点超过上限值 ②7 个点都在均值上，在临界值之下</p><ul><li>A．①检查</li><li>B．①②都要检查</li><li>C．①②都不需要检查</li><li>D．②检查</li></ul><details class="quiz" data-q="106" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：控制图出现以下情况需要检查：有点超出上下控制线、连续 7 点都在中心线一边、连续 7 点持续上升或下降，故①②都需检查（P501）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};